mat2 rot(float t){
    return mat2(cos(t), -sin(t), sin(t), cos(t));
}
float GetDist(vec3 p){
    float c = length(p-vec3(0.,-1.,6.))-3.;

    vec3 posc = p-vec3(0.,0.,6.);
    posc.xz *= rot(iTime);
    float cube = length(  max(abs(posc)-vec3(1.,1.,1.) ,0.) );
    return min(max(-c, p.y+0.5), cube);
}


float trace(vec3 ro, vec3 rd){
    float d = 0.;
    float dif = 0.;
    for(int i = 0; i < 100; i ++){
        vec3 p = ro+rd*d;
        float dp = GetDist(p);
        d += dp;
        if(d < 0.01 || d > 100.) break;
    }
    return d;
}
vec3 GetNorm(vec3 p){
    vec2 e = vec2(0., 0.01);
    float d = GetDist(p);
    vec3 n = d - vec3(
        GetDist(p-e.yxx),
        GetDist(p-e.xyx),
        GetDist(p-e.xxy)
    );

    return n;
}
float light(vec3 p){
    vec3 l = vec3(0., 10., 5.);

    vec3 lp = normalize(l-p);
    vec3 n = GetNorm(p);

    float dif = dot(lp,n);

    return dif;
}
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2. * fragCoord/iResolution.xy - 1.;
    uv.x *= iResolution.x/iResolution.y;
    vec2 uvv = uv;
    uvv *= fract(uvv * 50.)-0.5;
    vec3 ro = vec3(1.+cos(iTime), 1., -1.*sin(iTime));
    vec3 rd = vec3(uv.x+cos(iTime),uv.y-0.5, 1.);

    float t = trace(ro, rd);
    vec3 p = ro+rd*t;
    float l = light(p)*100.;

    vec3 col = vec3(length(uvv));
    col += l*0.8;

    fragColor = vec4(col,1.0);
}
